def memoize(fn):
    cache = {}
    def wrapped(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if cache.get(key):
            return cache[key]
        result = fn(*args, **kwargs)
        cache[key] = result
        return result
    return wrapped

cases.hidden_tests:
for value in (None,0,False,''):
    calls=[]
    @memoize
    def f(x, y=1):
        calls.append((x,y))
        return value
    assert f(3,y=2)==value and f(3,y=2)==value
    assert len(calls)==1
calls=[]
@memoize
def fail(x):
    calls.append(x)
    raise ValueError(x)
for i in range(2):
    try: fail(1)
    except ValueError: pass
    else: raise AssertionError('exception lost')
assert calls==[1,1]

