def chunks(items, size):
    for i in range(0, len(items), size):
        yield items[i:i + size]

cases.hidden_tests:
assert list(chunks((x for x in range(7)),3))==[[0,1,2],[3,4,5],[6]]
assert list(chunks(iter([]),1))==[]
assert list(chunks([1,2],1))==[[1],[2]]
for n in (0,-1):
    try: list(chunks([],n))
    except ValueError: pass
    else: raise AssertionError('invalid size accepted')
